/// <summary>
///     The <c>AVABPJobsUpdateResponsibilities</c> class is the execution class for <c>BP-Jobs</c>
/// </summary>
class AVABPJobsUpdateResponsibilities
{
    QueryRun                    queryRun;
    boolean                     lJobMode;
    boolean                     lCheckOnly;
    KCS_KBVBuildingProjectID    kcs_KBVBuildingProjectID;

    KCS_KBVBPCompanySpecific    kcs_KBVBPCompanySpecific;
    KCS_KBVLastRespUpdate       kcs_KBVLastRespUpdate;
    KCS_KBVParameters           kcs_KBVParameters;
    UTCTimestamp                kcs_MaxDate;
    container                   bvCompanies;

    container                   processinginterval;

}

Method.Source:
/// <summary>
/// N.Freidenberger 12.09.2025
/// </summary>
/// <param name = "_processingInterval">_processingInterval</param>
/// <returns>container</returns>
public container parmProcessingInterval(container       _processingInterval = processingInterval)
{
    processinginterval = _processingInterval;
    return processinginterval;
}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    lJobMode    = false;
    lCheckOnly  = false;
}

/// <summary>
///     AVA <c>initQuery</c> method.
/// </summary>
public void initQuery()
{
    Query                   query;
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildDataSource    buildingProjectDS;
    QueryBuildRange         qbr;
    str   fromBVNum, toBVNum, zeroRecord;

    query = new Query();
    queryBuildDataSource = query.addDataSource(tablenum(KCS_KBVBPCompanySpecific));
    queryBuildDataSource.addRange(fieldnum(KCS_KBVBPCompanySpecific, KCS_KBVBuildingProjectID));

    buildingProjectDS =   queryBuildDataSource.addDataSource(tableNum(KCS_KBVBuildingProjectTable));
    buildingProjectDS.joinMode(JoinMode::InnerJoin);
    buildingProjectDS.addLink(fieldNum(KCS_KBVBPCompanySpecific,KCS_KBVBuildingProjectID),fieldNum(KCS_KBVBuildingProjectTable,KCS_KBVBuildingProjectId));

    //queryRun = new QueryRun(query);

    //Filter Bauvorhaben
    qbr = AVABPJobsExecution::setKBVBuildingProjectIdRange( query,
                                                            tablenum(KCS_KBVBPCompanySpecific),
                                                            fieldnum(KCS_KBVBPCompanySpecific, KCS_KBVBuildingProjectID),
                                                            kcs_KBVBuildingProjectID);

 /*   buildingProjectDS.addRange(fieldNum(KCS_KBVBuildingProjectTable,KCS_KBVStatus)).value(strFmt('%1,%2,%3,%4',SysQuery::valueNot(KCS_KBVStatus::Locked),
        SysQuery::valueNot(KCS_KBVStatus::Won),SysQuery::valueNot(KCS_KBVStatus::Lost),SysQuery::valueNot(KCS_KBVStatus::Declined)));
    buildingProjectDS.addRange(fieldNum(KCS_KBVBuildingProjectTable,StatusModified)).value(strFmt('< %1',SysQuery::value((systemDateGet()-5))));   */

    buildingProjectDS.addRange(fieldNum(KCS_KBVBuildingProjectTable,RecId)).value(strFmt('((%1.%2 <= %3) || (%1.%4 == %5) || (%1.%4 == %6) || (%1.%4 == %7))',buildingProjectDS.name(),
                      fieldstr(KCS_KBVBuildingProjectTable,StatusModified),date2StrXpp(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - 5),fieldStr(KCS_KBVBuildingProjectTable,KCS_KBVStatus),
        any2Int(KCS_KBVStatus::Inquired),any2Int(KCS_KBVStatus::Answered),any2Int(KCS_KBVStatus::PartialWon)));

    if (conLen(processinginterval) > 0)
    {
        fromBVNum = conPeek(processinginterval,1);
        toBVNum   = conPeek(processinginterval,2);
        zeroRecord = conPeek(processinginterval,3);

        if (toBVNum != zeroRecord)
        {
            qbr.value(strFmt('%1..%2', fromBVNum, toBVNum));
        }
        else
        {
            qbr.value(strFmt('%1..', fromBVNum));
        }
    }

    queryRun = new QueryRun(query);
}

/// <summary>
///     AVA <c>parmKCS_KBVBuildingProjectID</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///     <c>KCS_KBVBuildingProjectID</c> as return value
/// </returns>
public KCS_KBVBuildingProjectID parmKCS_KBVBuildingProjectID(KCS_KBVBuildingProjectID _parmValue = kcs_KBVBuildingProjectID)
{
    kcs_KBVBuildingProjectID = _parmValue;

    return kcs_KBVBuildingProjectID;
}

/// <summary>
///     AVA <c>parmlJobMode</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean parmlJobMode(boolean _parmValue = lJobMode)
{
    lJobMode = _parmValue;

    return lJobMode;
}

/// <summary>
///     AVA <c>parmlCheckOnly</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean parmlCheckOnly(boolean _parmValue = lCheckOnly)
{
    lCheckOnly = _parmValue;

    return lCheckOnly;
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    AVAException        exception;
    int                 anzWarnings, anzErrors;

    #OCCRetryCount

    anzWarnings = 0;
    anzErrors   = 0;

    try
    {

        while (queryRun.next())
        {
            ttsbegin;
            if (queryRun.changed(tablenum(KCS_KBVBPCompanySpecific)))
            {
                kcs_KBVBPCompanySpecific = queryRun.get(tablenum(KCS_KBVBPCompanySpecific));

                if (lCheckOnly)
                {
                    info(strfmt("@NDX:NXAResponsibilityCheckForBP", curext(), kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID ));
                }

                if(!kcs_KBVBPCompanySpecific.isClosed())
                {
                    this.update();
                }
                else
                {
                    this.close();
                }
            }
            ttscommit;
        }

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                if (conLen(this.parmProcessingInterval()) > 0)
                {
                    error(strFmt("@NDX:NXABPUpdateConflictBatch",kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID));
                }
                else
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }


}

/// <summary>
///     AVA <c>update</c> method.
/// </summary>
void update()
{
    KCS_KBVBuildingProjectTable     kCS_KBVBuildingProjectTable;

    AVAKBVHelperClass::SetBPCompanySpecificData(kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID, kcs_KBVBPCompanySpecific.dataAreaId, lCheckOnly);

    kCS_KBVBuildingProjectTable = kCS_KBVBuildingProjectTable::find(kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID);

    //Schwellenwertprüfung auf BV-Parametern
    if(kcs_KBVBuildingProjectTable.checkLimit())
    {
        if (lCheckOnly)
        {
            info("@NDX:NXAThresholdLevelReached");
        }

        ttsbegin;
        //manuelle Zuständigkeit?
        if(kcs_KBVBPCompanySpecific.KCS_KBVSetMRManual == NoYes::Yes)
        {
            AVAKBVHelperClass::SetBPManualResponsibilities( kcs_KBVBPCompanySpecific, 
                                                            false, 
                                                            lCheckOnly  );
        }
        else
        {
            AVAKBVHelperClass::SetBPResponsibilities(   kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                        kcs_KBVBPCompanySpecific.dataAreaId,
                                                        false,
                                                        lCheckOnly  );
        }
        ttscommit;
    }
    /*else
    {
        if (!lJobMode)
        {
            info(strfmt("@NDX:NXAResponsibilityCompanyNotGenerated",    kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                        kcs_KBVBPCompanySpecific.dataAreaId)    );
        }
    }*/
}

/// <summary>
///     AVA <c>close</c> method.
/// </summary>
void close()
{
    KCS_KBVResponsibilitiesTable    kCS_KBVResponsibilitiesTable;

    //Zuständigkeiten beenden
    while select forupdate  kCS_KBVResponsibilitiesTable
    where   kCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID == kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID
        &&  !kCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate
    {
        kCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        ttsbegin;
        kCS_KBVResponsibilitiesTable.write();
        ttscommit;

        info(strfmt("@NDX:NXABPResponsibilityForCompanyTerminated", kCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID,
                                                                    HCMWorker::find(kCS_KBVResponsibilitiesTable.smmWorker).Name(),
                                                                    kCS_KBVResponsibilitiesTable.dataAreaId));
    }
}
